export function getCGMLAProfile(acNo: number): MLAProfile | undefined {
  return CG_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getCGMLAsByParty(party: string): MLAProfile[] {
  return CG_MLA_PROFILES.filter(p => p.party === party);
}

export function getCGFemaleMLAs(): MLAProfile[] {
  return CG_MLA_PROFILES.filter(p => p.gender === 'F');
}
